#!/usr/bin/env python3
"""Resolve the source branch for a friend dialogue commit, and repair
malformed/empty `Source:` lines in episode files.

Resolution order:
 1. exactly one origin/friend/* branch whose history contains the commit;
 2. otherwise the branch matching the commit's `Speaker:` header.
"""
import re, subprocess, sys, pathlib

REPO = "/tmp/shurik-workspace-Am8STp"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def run(*args):
    return subprocess.run(["git", "-C", REPO] + list(args), capture_output=True, text=True).stdout


def contains(branch, sha):
    return subprocess.run(["git", "-C", REPO, "merge-base", "--is-ancestor", sha, f"origin/friend/{branch}"]).returncode == 0


def resolve_branch(sha):
    matches = [b for b in BRANCHES if contains(b, sha)]
    if len(matches) == 1:
        return matches[0], "ancestry"
    body = run("show", "-s", "--format=%B", sha)
    m = re.search(r"^Speaker: (\w+)$", body, re.M)
    speaker = m.group(1).lower() if m else None
    if speaker in BRANCHES:
        return speaker, f"speaker-fallback(matches={matches})"
    raise SystemExit(f"cannot resolve branch for {sha} (matches={matches})")


def main():
    root = pathlib.Path(sys.argv[1])
    total = 0
    for path in sorted(root.glob("S*/E*.md")):
        text = path.read_text(encoding="utf-8")
        def fix(m):
            nonlocal total
            sha = m.group(2)
            branch, how = resolve_branch(sha)
            if m.group(1) != branch:
                print(f"{path}: repairing {sha[:10]}: '{m.group(1)}' -> '{branch}' ({how})")
                total += 1
            return f"Source: {branch} @ {sha}"
        new = re.sub(r"Source:\s*(\S*) @ ([0-9a-f]{40})", fix, text)
        if new != text:
            path.write_text(new, encoding="utf-8")
    print(f"lines repaired: {total}")


if __name__ == "__main__":
    main()

