#!/usr/bin/env python3
"""Validate episode files: frontmatter, summary duplication, entry format, SHA uniqueness."""
import pathlib, re, sys, yaml

root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "/tmp/wt-main")
files = sorted(root.glob("S*/E*.md"))
problems = []
seen = {}
for path in files:
    text = path.read_text(encoding="utf-8")
    parts = re.split(r"^---\s*$", text, maxsplit=2, flags=re.MULTILINE)
    if len(parts) != 3 or parts[0].strip():
        problems.append(f"{path}: bad frontmatter fences")
        continue
    meta = yaml.safe_load(parts[1])
    body = parts[2].strip()
    name = path.relative_to(root).as_posix()
    want = f"S{meta.get('season', 0):02d}/E{meta.get('episode', 0):02d}.md"
    if name != want:
        problems.append(f"{path}: filename != season/episode {meta.get('season')}/{meta.get('episode')}")
    if not isinstance(meta.get("title"), str) or not meta["title"].lower().startswith("the one with "):
        problems.append(f"{path}: title must start 'The One With '")
    if meta.get("status") not in ("ongoing", "complete"):
        problems.append(f"{path}: status must be ongoing/complete")
    summary = " ".join((meta.get("summary") or "").split())
    if not summary:
        problems.append(f"{path}: missing summary")
    words = len(summary.split())
    if not 15 <= words <= 45:
        problems.append(f"{path}: summary word count {words} outside 15-45")
    first_para = body.split("\n\n", 1)[0].strip()
    if " ".join(first_para.split()) != summary:
        problems.append(f"{path}: intro paragraph != frontmatter summary")
    blocks = re.split(r"\n\s*\n", body)
    expect_speaker = True
    for i, blk in enumerate(blocks):
        blk = blk.strip()
        if i == 0:
            continue  # summary paragraph
        if re.fullmatch(r"\*\*\w+\*\* \(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ\)", blk):
            expect_speaker = False
            continue
        m = re.fullmatch(r"Source: friend/(\w+) @ ([0-9a-f]{40})", blk)
        if m:
            if expect_speaker:
                problems.append(f"{path}: Source line without preceding speaker heading: {m.group(2)[:10]}")
            sha = m.group(2)
            if sha in seen:
                problems.append(f"{path}: duplicate Source {sha[:10]} also in {seen[sha]}")
            seen[sha] = name
            expect_speaker = True
            continue
        if expect_speaker:
            problems.append(f"{path}: dialogue before speaker/source: {blk[:50]!r}")
    if not expect_speaker:
        problems.append(f"{path}: dangling speaker heading without Source line")
counts = {}
for path in files:
    counts[path.as_posix()] = len(re.findall(r"^Source:", path.read_text(encoding="utf-8"), re.M))
print("entries per file:", counts, "total", sum(counts.values()))
if problems:
    print(f"PROBLEMS ({len(problems)}):")
    for p in problems:
        print("  -", p)
    sys.exit(1)
print("validation OK")

